// Minimal stand-in for the installed lodash: independent public functions.
function merge(a, b) { return Object.assign(a, b); }
function get(o, p) { return o == null ? undefined : o[p]; }
function pick(o, keys) { var out = {}; keys.forEach(function (k) { out[k] = o[k]; }); return out; }
function cloneDeep(v) { return JSON.parse(JSON.stringify(v)); }
function template(s) { return function () { return s; }; }
module.exports = { merge: merge, get: get, pick: pick, cloneDeep: cloneDeep, template: template };
